import{obterJSON,endereco,consultaLimpa,pontuarCorrespondencia,idiomas}from'./comum.js';
const A=v=>Array.isArray(v)?v:v==null?[]:[v],S=v=>String(v??'').trim();
function pdfAberto(x){const candidatos=[x?.best_oa_location,x?.primary_location,...A(x?.locations)].filter(Boolean);for(const l of candidatos){const pdf=endereco(l?.pdf_url);if(pdf&&l?.is_oa!==false)return pdf}const oa=endereco(x?.open_access?.oa_url);return oa&&/\.pdf(?:$|[?#])/i.test(oa)?oa:null}
export async function pesquisarOpenAlexPdf(q,o={}){q=consultaLimpa(q);if(!q)return{livros:[],total:0,temMais:false};try{const p=Math.max(1,o.pagina||1),u=new URL('/api/acervos-gratuitos',location.origin);u.searchParams.set('fonte','openalex');u.searchParams.set('q',q);u.searchParams.set('pagina',String(p));const d=await obterJSON(u,15000,2);if(d?.taxaLimite)return{livros:[],total:0,temMais:false};const itens=A(d?.results),livros=itens.map(x=>{const id=S(x.id).split('/').pop(),pdf=pdfAberto(x);if(!id||!pdf)return null;const origem=endereco(x?.best_oa_location?.landing_page_url)||endereco(x?.primary_location?.landing_page_url)||endereco(x.doi)||`https://openalex.org/${id}`;const autores=A(x.authorships).map(a=>S(a?.author?.display_name)).filter(Boolean);const l={id:`openalex:${id}`,fonte:'openalex',provedor:'OpenAlex · PDF aberto',titulo:S(x.display_name||x.title)||'Sem título',autores,idiomas:idiomas(x.language||[]),capa:null,descricao:[x.publication_year,x.type,x.cited_by_count!=null?`${x.cited_by_count} citações`:null].filter(Boolean).join(' · '),acessoLivre:true,dominioPublico:false,tipoAcesso:'PDF aberto',licenca:S(x?.best_oa_location?.license||x?.primary_location?.license||x?.open_access?.oa_status)||'Acesso aberto indicado pelo OpenAlex.',origem,ler:pdf,texto:null,formatos:[{tipo:'PDF',url:pdf}],doi:x.doi||null};l.relevancia=pontuarCorrespondencia(q,l.titulo,l.autores)+1000;return l}).filter(Boolean);const total=Number(d?.meta?.count)||livros.length;return{livros,total,temMais:p*20<total&&itens.length>0}}catch{return{livros:[],total:0,temMais:false}}}
